package io.github.devjardins.sidespeed.companion.tv

import com.flyfishxu.kadb.cert.KadbCert
import com.flyfishxu.kadb.cert.KadbPrivateKeyStore
import java.io.File
import java.io.IOException
import java.security.MessageDigest
import java.security.cert.CertificateFactory
import java.nio.file.Files
import java.nio.file.attribute.PosixFileAttributeView
import java.nio.file.attribute.PosixFilePermissions

/**
 * The companion's ADB key: one RSA key, generated by Kadb on first use and kept in [KEY_FILE_NAME] under the
 * platform key directory (Android: `noBackupFilesDir/adb`; desktop: [DesktopDirs.keyDir]). The TV remembers it after
 * "Always allow", so it must survive restarts.
 *
 * Kadb holds its identity in a process-wide singleton, so this configures it once per key file.
 */
object CompanionKeys {
    const val KEY_FILE_NAME = "adbkey.pem"

    private var configuredFor: String? = null

    /** Points Kadb at the key under [keyDir], generating and saving it if absent. Blocking. */
    @Synchronized
    fun ensureReady(keyDir: File) {
        val file = File(keyDir, KEY_FILE_NAME).absoluteFile
        if (configuredFor != file.path) {
            KadbCert.configure(FilePrivateKeyStore(file))
            configuredFor = file.path
        }
        KadbCert.ensureReady()
    }

    /**
     * First 16 hex characters of the SHA-256 of [publicKey] (the key's encoded form, not the certificate
     * wrapped around it). Phone and desktop each get their own id, so each gets its own file on the TV.
     */
    fun companionId(publicKey: ByteArray): String {
        require(publicKey.isNotEmpty()) { "public key is empty" }
        return MessageDigest.getInstance("SHA-256").digest(publicKey).toHex().take(16)
    }

    /** The id of the key [ensureReady] last configured. The same key always produces the same id. */
    fun currentCompanionId(): String {
        val pem = KadbCert.exportIdentityOrNull()?.certificatePem ?: error("Companion key is not ready")
        val cert = CertificateFactory.getInstance("X.509").generateCertificate(pem.inputStream())
        return companionId(cert.publicKey.encoded)
    }
}

/**
 * A private key PEM in one file, written atomically. On POSIX systems (macOS, Linux, Android) the directory is
 * 0700 and the file 0600, and failing to apply that is an error. On Windows the per-user app-data directory's
 * ACL already restricts access; the owner-only calls there are best effort apart from the owner's own grants.
 */
internal class FilePrivateKeyStore(private val file: File) : KadbPrivateKeyStore {
    override fun readPrivateKeyPem(): ByteArray? = if (file.isFile) file.readBytes() else null

    override fun writePrivateKeyPemAtomic(privateKeyPem: ByteArray) {
        val dir = file.absoluteFile.parentFile ?: throw IOException("No directory for $file")
        if (!dir.isDirectory && !dir.mkdirs()) throw IOException("Cannot create $dir")
        restrict(dir, POSIX_DIR)
        val tmp = File(dir, "${file.name}.tmp")
        tmp.delete()
        if (!tmp.createNewFile()) throw IOException("Cannot create $tmp")
        restrict(tmp, POSIX_FILE)
        tmp.writeBytes(privateKeyPem)
        if (!tmp.renameTo(file)) {
            file.delete()
            if (!tmp.renameTo(file)) throw IOException("Cannot write $file")
        }
    }

    override fun clear() {
        file.delete()
    }

    private fun restrict(f: File, posix: String) {
        val path = f.toPath()
        if (Files.getFileAttributeView(path, PosixFileAttributeView::class.java) != null) {
            Files.setPosixFilePermissions(path, PosixFilePermissions.fromString(posix)) // throws on failure
        } else {
            f.setReadable(false, false)
            f.setWritable(false, false)
            val ownerOk = f.setReadable(true, true) and f.setWritable(true, true)
            // Windows reports false for directories and inherits the per-user app-data ACL anyway: best effort
            // there only. A non-POSIX filesystem on macOS or Linux (exFAT, a network mount) must still fail.
            if (!ownerOk && !System.getProperty("os.name").orEmpty().startsWith("Windows", ignoreCase = true)) {
                throw IOException("Cannot restrict $f to its owner")
            }
        }
    }

    private companion object {
        const val POSIX_DIR = "rwx------"
        const val POSIX_FILE = "rw-------"
    }
}
